<?php
    class ListStatisticsHandler extends Handler {
        public function handle($input) {
            global $processorProvider;

            $response = NULL;
            if (count($input) !== 1) {
                $response = $processorProvider->run("GetStats", array("type" => "all"));
            }
            else {
                if (isset($input["yearId"])) {
                    $response = $processorProvider->run("GetStats", array("type" => "year", "id" => $input["yearId"]));
                }
                else if (isset($input["tripId"])) {
                    $response = $processorProvider->run("GetStats", array("type" => "trip", "id" => $input["tripId"]));
                }
                else if (isset($input["categoryId"])) {
                    $response = $processorProvider->run("GetStats", array("type" => "category", "id" => $input["categoryId"]));
                }
                else {
                    $response = $processorProvider->run("GetStats", array("type" => "all"));
                }
            }

            return $this->createResponse(200, $response);
        }

        public function getTag() {
            return "Statistics";
        }

        public function getPath() {
            return "/statistics";
        }

        public function getParameters() {
            return array(
                $this->createQueryParameter("yearId", "integer", 2024),
                $this->createQueryParameter("tripId", "integer", 128),
                $this->createQueryParameter("categoryId", "integer", 1));
        }

        public function getMethod() {
            return "GET";
        }

        public function getOperationId() {
            return "list_statistics";
        }
        
        public function getShortDescription() {
            return "Retrieve a collection of statistics";
        }
        
        public function getLongDescription() {
            global $databaseProvider;
            $statisticsNames = $databaseProvider
                ->statementBuilder("SELECT CONCAT('``', name, '``') AS name FROM definition_statistics")
                ->getResultSetForColumn("name");
                $statisticsUnits = $databaseProvider
                    ->statementBuilder("SELECT DISTINCT CONCAT('``', unit, '``') AS unit FROM definition_statistics")
                    ->getResultSetForColumn("unit");

            return "Retrieves a collection of statistics matching the specified filters. Filters are exclusive, only one filter can be specified in one request. All filters are ignored otherwise. The allowed statistics types are: " . implode(", ", $statisticsNames) . ". The allowed statistics units are: " . implode(", ", $statisticsUnits);
        }
        
        public function getRequestExamples() {
            return array();
        }

